"""Parity fixture generated by ZipStrain's Python profiler."""

from importlib.metadata import entry_points
from pathlib import Path
import shutil
import subprocess

import polars as pl
import pyarrow.parquet as pq
import pytest

from zipstrain.profile_backends import ProfileRequest, run_profile


DATA = Path(__file__).parent / "data"


@pytest.mark.skipif(
    not entry_points(group="zipstrain.profile_backends", name="rust_profiler"),
    reason="The compiled Rust plugin wheel is not installed",
)
def test_installed_backend_matches_python_fixture(tmp_path):
    run_profile(
        ProfileRequest(
            bam_file=DATA / "small.bam",
            bed_file=DATA / "small.bed",
            stb_file=DATA / "small.stb",
            null_model=DATA / "null_model.parquet",
            gene_range_table=DATA / "genes.tsv",
            output_dir=tmp_path,
            num_chunks=8,
            max_concurrency=4,
            min_read_ani=0.0,
            read_inclusion="all-mapped",
        ),
        "rust_profiler",
    )

    name = "small_profile.parquet"
    actual = pq.ParquetFile(tmp_path / name)
    expected = pq.ParquetFile(DATA / "expected" / name)
    assert actual.schema_arrow.remove_metadata() == expected.schema_arrow.remove_metadata()
    assert actual.metadata.num_rows == expected.metadata.num_rows == 9982
    for key in (
        b"zipstrain_sorted_by",
        b"zipstrain_reference_hash",
        b"zipstrain_gene_hash",
        b"zipstrain_null_model_hash",
        b"zipstrain_stb_hash",
    ):
        assert actual.metadata.metadata.get(key) == expected.metadata.metadata.get(key)
    assert actual.read().equals(expected.read())

    for suffix, keys in (("gene_stats", ["genome", "gene"]), ("genome_stats", ["genome"])):
        name = f"small_{suffix}.parquet"
        got = pl.read_parquet(tmp_path / name).sort(keys)
        want = pl.read_parquet(DATA / "expected" / name).sort(keys)
        assert got.columns == want.columns
        assert got.shape == want.shape
        for actual_row, expected_row in zip(got.iter_rows(named=True), want.iter_rows(named=True)):
            for column, expected_value in expected_row.items():
                actual_value = actual_row[column]
                if isinstance(expected_value, float):
                    assert actual_value == pytest.approx(expected_value, rel=1e-10, abs=1e-10)
                else:
                    assert actual_value == expected_value


@pytest.mark.skipif(
    not entry_points(group="zipstrain.profile_backends", name="rust_profiler"),
    reason="The compiled Rust plugin wheel is not installed",
)
def test_installed_backend_builds_missing_bam_index(tmp_path):
    bam = tmp_path / "unindexed.bam"
    shutil.copyfile(DATA / "small.bam", bam)
    run_profile(
        ProfileRequest(
            bam_file=bam,
            bed_file=DATA / "small.bed",
            stb_file=DATA / "small.stb",
            null_model=DATA / "null_model.parquet",
            gene_range_table=DATA / "genes.tsv",
            output_dir=tmp_path / "out",
            num_chunks=2,
            max_concurrency=2,
        ),
        "rust_profiler",
    )
    assert bam.with_suffix(".bam.bai").is_file()
    assert (tmp_path / "out" / "unindexed_profile.parquet").is_file()


@pytest.mark.skipif(
    not entry_points(group="zipstrain.profile_backends", name="rust_profiler")
    or not shutil.which("samtools"),
    reason="The compiled Rust plugin and samtools are required",
)
@pytest.mark.parametrize(("pairs", "fug_defined"), [(2000, True), (2001, False)])
def test_reads_mapped_survives_zero_expected_gap(tmp_path, pairs, fug_defined):
    genome_length = 1000
    bed, stb = tmp_path / "ref.bed", tmp_path / "ref.stb"
    bed.write_text(f"chr\t0\t{genome_length}\n")
    stb.write_text("chr\tgenome\n")

    sam, bam = tmp_path / "reads.sam", tmp_path / "reads.bam"
    seq, qual = "A" * 100, "I" * 100
    with sam.open("w") as handle:
        handle.write(f"@HD\tVN:1.6\tSO:unsorted\n@SQ\tSN:chr\tLN:{genome_length}\n")
        for i in range(pairs):
            # Space first mates by two bases so FUG has nonzero excess gaps
            # before the rounded expected spacing drops to zero.
            left = 1 + 2 * (i % 400)
            right = left + 100
            handle.write(f"p{i}\t99\tchr\t{left}\t60\t100M\t=\t{right}\t200\t{seq}\t{qual}\n")
            handle.write(f"p{i}\t147\tchr\t{right}\t60\t100M\t=\t{left}\t-200\t{seq}\t{qual}\n")
    subprocess.run(["samtools", "sort", "-o", str(bam), str(sam)], check=True)

    out = tmp_path / "out"
    run_profile(
        ProfileRequest(
            bam_file=bam,
            bed_file=bed,
            stb_file=stb,
            null_model=DATA / "null_model.parquet",
            output_dir=out,
            num_chunks=1,
            max_concurrency=1,
            read_inclusion="proper-pairs",
        ),
        "rust_profiler",
    )

    mapped, fug = pl.read_parquet(out / "reads_genome_stats.parquet").select("reads_mapped", "fug").row(0)
    assert mapped == pairs
    assert (fug is not None) == fug_defined
